"""Tests for rewii.core.online (GXGlobal.cfg editing)."""
from __future__ import annotations

import pytest

from rewii.core import online as O
from rewii.core.layout import DriveLayout

EXISTING = """# USB Loader GX R1283 - Main settings file
# Note: This file is automatically generated
godmode = 1
language = 1
PrivateServer = 0
CustomAddress = wiimmfi.de
GameCubePath = usb1:/games/
"""


def test_create_new_file_has_valid_header(tmp_path):
    layout = DriveLayout(tmp_path)
    assert O.read_gx_config(layout) == {}
    assert O.set_loader_private_server(layout, "wiimmfi") == 2
    text = layout.gx_config.read_text()
    assert text.splitlines()[0] == O.GX_HEADER
    assert O._has_valid_header(text.splitlines())
    assert O.read_gx_config(layout) == {"PrivateServer": "2"}


def test_edit_preserves_other_lines(tmp_path):
    layout = DriveLayout(tmp_path)
    layout.gx_config.parent.mkdir(parents=True)
    layout.gx_config.write_text(EXISTING)
    O.set_loader_private_server(layout, "custom", "example.org")
    lines = layout.gx_config.read_text().splitlines()
    assert lines[:4] == EXISTING.splitlines()[:4]
    cfg = O.read_gx_config(layout)
    assert cfg["PrivateServer"] == "4" and cfg["CustomAddress"] == "example.org"
    assert cfg["godmode"] == "1" and cfg["GameCubePath"] == "usb1:/games/"
    assert sum(1 for line in lines if line.startswith("PrivateServer")) == 1
    O.set_loader_private_server(layout, "")
    assert O.read_gx_config(layout)["PrivateServer"] == "0"


def test_write_add_remove_and_old_header(tmp_path):
    layout = DriveLayout(tmp_path)
    layout.gx_config.parent.mkdir(parents=True)
    layout.gx_config.write_text("# USB Loader GX R900\nfoo = bar\n")
    cfg = O.write_gx_config(layout, {"BannerAnimStart": 1, "foo": None})
    assert cfg == {"BannerAnimStart": "1"}
    assert layout.gx_config.read_text().splitlines()[0] == O.GX_HEADER   # old rev would be ignored


def test_rejects_bad_input(tmp_path):
    layout = DriveLayout(tmp_path)
    with pytest.raises(O.UnsupportedServer):
        O.set_loader_private_server(layout, "wiilink")
    with pytest.raises(ValueError):
        O.set_loader_private_server(layout, "custom", "ab")
    with pytest.raises(ValueError):
        O.set_loader_private_server(layout, "nintendo")
    with pytest.raises(ValueError):
        O.write_gx_config(layout, {"x": "a\nb = c"})
    assert not layout.gx_config.exists()


def test_options_table():
    assert O.GX_OPTIONS["PrivateServer"].choices["2"] == "Wiimmfi"
    assert O.GX_OPTIONS["GameCubeMode"].choices["2"] == "Nintendont"
    assert set(O.PRIVATE_SERVERS.values()) == {0, 1, 2, 3, 4}


def test_rewrite_keeps_non_utf8_bytes_in_other_lines(tmp_path):
    layout = DriveLayout(tmp_path)
    layout.gx_config.parent.mkdir(parents=True)
    raw = (b"# USB Loader GX R1283 - Main settings file\r\n"
           b"titlestxt_path = usb1:/jeux pr\xe9f\xe9r\xe9s/\r\n"      # latin-1, not UTF-8
           b"PrivateServer = 0\r\n")
    layout.gx_config.write_bytes(raw)
    O.set_loader_private_server(layout, "wiimmfi")
    out = layout.gx_config.read_bytes()
    assert b"titlestxt_path = usb1:/jeux pr\xe9f\xe9r\xe9s/\n" in out
    assert b"PrivateServer = 2\n" in out and "\ufffd".encode() not in out
    assert O.read_gx_config(layout)["PrivateServer"] == "2"
    assert not list(layout.gx_config.parent.glob("*.tmp"))
    with pytest.raises(ValueError):
        O.write_gx_config(layout, {"#comment": "1"})
